reactions.evaluate:
// Max 1 stack
if (api.findEffectsOnToken(reactorToken, "invisible", {hasFlags: ["flicker_field"]}).length > 0) return false;

// We don't have a stack and we're boosting
if (triggerData.actionName === "Boost") return true;
// Is this a regular move on our turn?
if (game.combat?.combatant?.tokenId == reactorToken.id && triggerType == 'onMove'){
    const moveInfo = triggerData.moveInfo;
    return (! (moveInfo.isInvoluntary || moveInfo.isTeleport || moveInfo.isFreeMovement));
}

return false;

reactions.activationCode:
// apply will be a Boost activation or an onMove. If it's an onMove,
// it's from our standard move, and should be limited to once per turn.
// otherwise, it's from a boost and can be as often as we boost.

// we've already filtered out nonstandard movement in the evaluate.
if (triggerType === 'onMove'){
    // This really should be once per turn but realistically players only get one turn per round
    if (! await api.consumeOncePerRound(reactorToken, 'flicker_field_standard_move')) return;
}

await api.applyEffectsToTokens({
    	tokens: [reactorToken],
    	effectNames: 'invisible',
    	note: 'Flicker Field Projector (1 charge)',
    	notify: {source: item.name, whisper: false},
	},{
    	stack: 1,
    	consumption: {
        	trigger: ['onHit', 'onMiss', 'onTechHit', 'onTechMiss'],
    		role: 'target',
        },
        flicker_field: true,
    }
);

reactions.evaluate:
// Trigger on onUpdate not onMove so that the final distance is correct.
// On an update that has some defined movement, check the distance for adjacency
if (['x', 'y', 'elevation'].some(k => triggerData.change?.[k] !== undefined)) {
        return triggerData.distanceToTrigger <= 1;
}

return false;

reactions.activationCode:
await Promise.all([
    api.setReaction(reactorToken, false),
	api.activateGeneralAction(reactorToken, 'Boost'),
    api.addGlobalBonus(
        reactorToken.actor,
		{
            name: "Spatial Awareness",
            type: "difficulty",
            val: 1,
            rollTypes: ["attack"],
            applyToTargetter: true
        },{
            duration: 'end',
            durationTurns: 1,
            origin: reactorToken,
            refresh: true
        })
]);

reactions.evaluate:
switch (triggerType) {
    case "onTurnEnd":
        // We have to check here early otherwise the suppression will have 
        // already been removed by the time the activation code runs.
        return ! api.findEffectOnToken(reactorToken, "Regeneration Suppression");
    default:
        return true;
}

reactions.activationCode:
switch (triggerType) {
    // If we are suppressed, this will not fire since the evaluation will skip it.
    case 'onTurnEnd': {
        const actor = reactorToken.actor;
        const { value: hpCur, max: hpMax } = actor.system.hp;
        const hpMissing = hpMax - hpCur

        if (hpMissing <= 0) break; // Nothing to regenerate

        // this is the divisor for the regen, so half (2.0) when core is active, a quarter (4.0) otherwise.
        const regenFactor = api.hasStatus(reactorToken, 'core_power_active') ? 2 : 4;
        const regen = Math.min(Math.ceil(hpMax / regenFactor), hpMissing);

        actor.modifyTokenAttribute('hp', regen, true, true); // no need to await this
        ChatMessage.create({
            speaker: ChatMessage.getSpeaker({ actor }),
            content: `<b>${actor.name}</b> regenerated ${regen} ${game.i18n.localize('lancer.common-sheet.shortStats.hp')}.`
        });
        break;
    }
    case 'onStructure':
    case 'onStress':
        api.applyEffectsToTokens(
            {
                tokens: [reactorToken],
                effectNames: {name: 'Regeneration Suppression', icon: 'modules/lancer-automations/icons/pause-button.svg', isCustom: true},
                note: 'Suppresses end of turn Balor regeneration',
                duration: api.untilEndOfTurn(reactorToken),
                refresh: true
            }
        );
        break;
}

const actor = reactorToken.actor;
const { confirmed } = await api.askCard({
    title: 'Balor Self-Perpetuating',
    description: `${actor.name} may regenerate full HP without spending repairs if you rest.`,
    yesText: 'Rest',
    yesIcon: 'fas fa-first-aid',
    noText: 'No Rest',
    owner: reactorToken,
    originToken: reactorToken
});

if (confirmed){
    await actor.update({ 'system.hp.value': actor.system.hp.max });
    ChatMessage.create({
        speaker: ChatMessage.getSpeaker({ actor }),
        content: `<b>${actor.name}</b> regenerates all HP via Self-Perpetuating.`
    });
}

const turnTokenId = triggerData.triggeringToken.id
const turnActorId = triggerData.triggeringToken.actor.uuid;

// Collect any tokens including deployables in range 1 that are the triggering token, or owned by the triggering token
let adjacentTokens = api.getTokensInRange(
    reactorToken, 
    {
        range: 1,
        includeHidden: true,
        includeDeployables: true,
        includeElevation: true,
        filter: (token) => (token.id === turnTokenId || token.document.getFlag('lancer-automations', 'ownerActorUuid') === turnActorId),
    }
);

if (adjacentTokens.length < 1) return;

let core = api.hasStatus(reactorToken, 'core_power_active')? 4 : 2;
await api.executeDamageRoll(reactorToken, adjacentTokens, core, 'kinetic', 'Scouring Swarm');

await api.addGlobalBonus(
    reactorToken.actor,
    {
        id: 'everest_powerup_acc',
        name: 'Power Up',
        type: 'accuracy',
        val: 1,
        rollTypes: ['attack', 'tech_attack', 'check'],
    },
    {
        duration: 'indefinite',
        consumption: { trigger: 'onExitCombat' },
    }
);
